<?php
declare(strict_types=1);require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/helpers.php';
$file=__DIR__.'/curriculum/grade8-science-unit1.json';if(!is_file($file))throw new RuntimeException('Missing Grade 8 Science short-notes data.');$data=json_decode((string)file_get_contents($file),true,512,JSON_THROW_ON_ERROR);$db=db();
$lesson=query_one("SELECT l.id,l.grade_id,l.subject_id,l.unit_id FROM lessons l JOIN grades g ON g.id=l.grade_id JOIN subjects s ON s.id=l.subject_id JOIN units u ON u.id=l.unit_id WHERE g.grade_number=8 AND s.name_en='Science' AND l.medium='Sinhala' AND l.status='active' AND l.content_source='textbook' AND u.unit_number=1 ORDER BY l.id LIMIT 1");if(!$lesson)throw new RuntimeException('Active Grade 8 Sinhala Science lesson 1 was not found.');
$column=$db->query("SHOW COLUMNS FROM lessons LIKE 'short_notes_si'");if(!$column||$column->num_rows===0)$db->query("ALTER TABLE lessons ADD short_notes_si MEDIUMTEXT NULL AFTER short_description_si");
$notes=(string)file_get_contents(__DIR__.'/curriculum/grade8-science-unit1-short-notes.txt');$description=(string)$data['short_description'];$summary=implode("\n",array_map(fn($x)=>'- '.$x,$data['summary']));$terms=implode(', ',$data['key_terms']);$s=$db->prepare("UPDATE lessons SET short_description_si=?,short_notes_si=?,summary_si=?,key_terms_si=? WHERE id=?");$s->bind_param('ssssi',$description,$notes,$summary,$terms,$lesson['id']);$s->execute();
$quiz=query_one('SELECT id FROM quizzes WHERE lesson_id=? ORDER BY id LIMIT 1','i',[$lesson['id']]);if(!$quiz){$s=$db->prepare("INSERT INTO quizzes(grade_id,subject_id,unit_id,lesson_id,title_si,timer_minutes,pass_mark,status) VALUES(?,?,?,?,'ක්ෂුද්‍ර ජීවීන්ගේ වැදගත්කම - පුහුණු ප්‍රශ්න',15,50,'active')");$s->bind_param('iiii',$lesson['grade_id'],$lesson['subject_id'],$lesson['unit_id'],$lesson['id']);$s->execute();$quizId=(int)$db->insert_id;}else $quizId=(int)$quiz['id'];
$db->query("DELETE FROM quiz_questions WHERE quiz_id=$quizId");foreach($data['questions'] as $i=>$q){$o=$q['options'];$order=$i+1;$s=$db->prepare("INSERT INTO quiz_questions(quiz_id,question_si,option_a_si,option_b_si,option_c_si,option_d_si,correct_option,explanation_si,display_order,status) VALUES(?,?,?,?,?,?,?,?,?,'active')");$s->bind_param('isssssssi',$quizId,$q['question'],$o[0],$o[1],$o[2],$o[3],$q['correct'],$q['explanation'],$order);$s->execute();}echo 'Imported Grade 8 Science Unit 1 short notes and '.count($data['questions'])." practice questions.\n";
